// Editing is restricted to the tactics dialog; live pitch stays read-only.
var tacticalDrag=null;
function tacticalDropPoint(rect,x,y){return [Math.max(7,Math.min(93,Math.round((x-rect.left)/rect.width*100))),Math.max(8,Math.min(92,Math.round((y-rect.top)/rect.height*100)))];}
function commitTacticalPosition(id,point){
 if(!editable()||!state.lineup.includes(id))return;
 const p=state.players[id];customPositions[p.identity]=point;selected=id;save();render();
 const pos=F.assignedPosition(...point,p.pos);$('tactical-position-status').textContent=p.name+' · '+pos.code+' '+pos.label+' 배치 완료';
 $('tactical-editor').querySelector('[data-tactical-player="'+id+'"]')?.focus({preventScroll:true});
}
function tacticalTraitMarkup(row){
 if(!row)return '';
 const p=row.p,position=F.assignedPosition(row.x,row.y,p.pos),fit=PlayerTraits.suitability(p,position.code),feet=PlayerTraits.feet(p),form=PlayerTraits.condition(season,p);
 const top=PlayerTraits.allPositions(p).filter(pos=>pos.code!=='GK'||p.pos==='GK').sort((a,b)=>b.score-a.score||a.code.localeCompare(b.code)).slice(0,4);
 return '<div class="tactical-selected-profile"><strong>'+escapeText(p.name)+' · 현재 '+position.code+' 적합도 '+fit+'</strong><p>주발 '+escapeText(feet.label)+' · 왼발 '+feet.left+'/5 · 오른발 '+feet.right+'/5 · 컨디션 '+escapeText(form.label)+(form.score===null?'':' '+form.score)+'</p><div>'+top.map(pos=>'<span>'+pos.code+' '+pos.score+'</span>').join('')+'</div><small>포지션 적합도는 전술 선택을 돕는 코치 분석입니다.</small></div>';
}
function setPieceAssignmentMarkup(canEdit){
 if(!state||state.version<8||!state.setPieces)return '';
 const roles=Object.entries(F.setPieceRoleNames),field=state.lineup.map(id=>state.players[id]).filter(p=>p&&p.pos!=='GK'&&F.isAvailable(p)&&!Discipline.dismissed(state).includes(p.id));
 return '<section class="set-piece-plan" aria-labelledby="set-piece-plan-title"><div><span class="eyebrow">SET PIECE / DEAD-BALL PLAN</span><h3 id="set-piece-plan-title">세트피스 키커와 타깃</h3><p>상대 수비를 흔들 준비를 하세요. 코너와 직접 프리킥이 경기 장면·기대 득점에 반영됩니다.</p></div>'+roles.map(([role,label])=>{const assigned=field.find(p=>p.id===state.setPieces[role])||state.players[F.defaultSetPieces(state,field.map(p=>p.id))[role]],preference=state===season.match?season.plan.setPieces?.[role]:null,person=preference?F.identityProfile(preference):null,fallback=person&&person.identity!==assigned?.identity,options=[...field].sort((a,b)=>F.setPieceScore(b,role)-F.setPieceScore(a,role)||a.id.localeCompare(b.id));return '<label class="set-piece-role"><span>'+label+'<small>'+escapeText(person?(fallback?person.name+' 대신 이번 경기 대체':'우선 담당: '+person.name):'이번 선발에서 자동 선택')+'</small></span><select data-set-piece-role="'+role+'" aria-label="'+label+' 선택" '+(!canEdit||state.phase!=='prep'?'disabled':'')+'><option value="auto">자동 선택으로 변경</option>'+options.map(p=>'<option value="'+p.id+'" '+(p.id===assigned?.id?'selected':'')+'>'+escapeText(p.name)+' · '+p.pos+' · '+F.setPieceScore(p,role)+'</option>').join('')+'</select></label>';}).join('')+'<p class="set-piece-note">영입 선수도 선발에 넣은 뒤 지정할 수 있습니다. 지정은 선수 신원으로 다음 경기까지 기억합니다. 후보·부상·출전 정지 때는 대체 선수가 맡고, 다시 선발에 들면 우선 담당이 돌아옵니다. 이적하면 지정이 해제됩니다. 경기 중 교체·퇴장은 현재 필드에서 자동 대체합니다. 지표는 현재 공격·패스·수비·스피드·지구력으로 계산합니다.</p></section>';
}
function renderTacticalEditor(){
 const host=$('tactical-editor');if(!host||!state||tacticalDrag)return;
 const briefingOpen=Boolean(host.querySelector('.touchline-briefing')?.open),canEdit=editable(),rows=positions().filter(row=>!Discipline.dismissed(state).includes(row.id)),chosen=rows.find(row=>row.id===selected),plan=TouchlinePlan.read(season,rows.map(r=>({...r,roleFit:typeof roleSuitability==='function'?roleSuitability(r.p,playerRole(r.p)[0]):undefined,roleName:typeof playerRole==='function'?playerRole(r.p)[1]:undefined})),selected);
 host.innerHTML='<h3>선수 배치와 역할</h3><p>유니폼을 누른 채 원하는 곳으로 끌어 놓으세요. 위치에 따라 배치 포지션이 바뀝니다. 키보드는 선수 선택 후 방향키로 이동합니다.</p><div class="tactical-team-strip">선발 종합 평균 <b>'+plan.team.overall+'</b> · 체력 평균 <b>'+plan.team.energy+'</b></div><label class="support-map-toggle"><input id="support-map-toggle" type="checkbox" '+(supportMapVisible?'checked':'')+'/> 가까운 동료 연결 표시</label><div class="tactical-pitch" role="group" aria-label="드래그로 선수 배치 · 공격 방향 위쪽">'+(supportMapVisible?supportMapSvg(plan):'')+'<span class="tactical-direction" aria-hidden="true">공격 방향 ↑</span>'+rows.map(({id,p,x,y})=>{const pos=F.assignedPosition(x,y,p.pos),rating=TouchlinePlan.overall(p),energy=Math.round(p.energy),fit=PlayerTraits.suitability(p,pos.code),form=PlayerTraits.condition(season,p);return '<button type="button" data-tactical-player="'+id+'" aria-label="'+escapeText(p.name+' · '+pos.code+' '+pos.label+' · 종합 '+rating+' · 체력 '+energy+' · 배치 적합도 '+fit+' · 컨디션 '+form.label+' · 방향키로 이동')+'" aria-pressed="'+(selected===id)+'" '+(!canEdit?'disabled':'')+' style="left:'+x+'%;top:'+y+'%">'+Portraits.html(p)+'<b>'+p.no+' <em>'+pos.code+'</em></b><span>'+escapeText(p.name)+'</span></button>';}).join('')+'</div><p id="tactical-position-status" role="status" aria-live="polite">'+(chosen?escapeText(chosen.p.name)+' · 배치 '+F.assignedPosition(chosen.x,chosen.y,chosen.p.pos).code+' · 주 포지션 '+chosen.p.pos:'선수를 끌어 놓거나 선택하세요.')+'</p>'+tacticalTraitMarkup(chosen)+setPieceAssignmentMarkup(canEdit)+touchlineMarkup(plan)+'<p class="tactical-note">배치 포지션은 경기장의 출발 위치입니다. 선수의 주 포지션과 교체 등록 포지션은 유지됩니다. 포메이션을 바꾸면 새 기본 배치로 정렬합니다.</p>';
 const briefing=host.querySelector('.touchline-briefing');if(briefing)briefing.open=briefingOpen;
 host.onchange=event=>{if(event.target.matches('[data-set-piece-role]')){const role=event.target.dataset.setPieceRole;if(state!==season.match)F.assignSetPieceRole(state,role,event.target.value==='auto'?F.defaultSetPieces(state,state.lineup)[role]:event.target.value);else if(event.target.value==='auto')S.autoSetPiece(season,role);else S.assignSetPiece(season,role,event.target.value);save();render();$('tactical-editor').querySelector('[data-set-piece-role="'+role+'"]')?.focus({preventScroll:true});return;}if(event.target.id!=='support-map-toggle')return;supportMapVisible=event.target.checked;renderTacticalEditor();$('support-map-toggle')?.focus({preventScroll:true});};
 host.onclick=event=>{const b=event.target.closest('[data-tactical-player]');if(!b||!canEdit||tacticalDrag)return;selected=b.dataset.tacticalPlayer;save();render();host.querySelector('[data-tactical-player="'+selected+'"]')?.focus({preventScroll:true});};
 host.onpointerdown=event=>{const b=event.target.closest('[data-tactical-player]');if(!b||!canEdit||event.button!==0||tacticalDrag)return;const row=rows.find(row=>row.id===b.dataset.tacticalPlayer);selected=row.id;tacticalDrag={id:row.id,pointer:event.pointerId,button:b,rect:b.parentElement.getBoundingClientRect(),point:[row.x,row.y]};b.setPointerCapture(event.pointerId);b.classList.add('dragging');const map=host.querySelector('.support-map');if(map)map.style.visibility='hidden';event.preventDefault();};
 host.onpointermove=event=>{const d=tacticalDrag;if(!d||event.pointerId!==d.pointer)return;d.point=tacticalDropPoint(d.rect,event.clientX,event.clientY);d.button.style.left=d.point[0]+'%';d.button.style.top=d.point[1]+'%';const p=state.players[d.id],pos=F.assignedPosition(...d.point,p.pos);d.button.querySelector('em').textContent=pos.code;$('tactical-position-status').textContent=p.name+' · '+pos.code+' '+pos.label;event.preventDefault();};
 host.onpointerup=event=>{const d=tacticalDrag;if(!d||event.pointerId!==d.pointer)return;tacticalDrag=null;d.button.releasePointerCapture(event.pointerId);commitTacticalPosition(d.id,d.point);};
 host.onpointercancel=host.onlostpointercapture=event=>{if(!tacticalDrag||event.pointerId!==tacticalDrag.pointer)return;tacticalDrag=null;render();};
 host.onkeydown=event=>{const b=event.target.closest('[data-tactical-player]'),delta={ArrowLeft:[-2,0],ArrowRight:[2,0],ArrowUp:[0,-2],ArrowDown:[0,2]}[event.key];if(!b||!delta||!canEdit)return;event.preventDefault();const row=positions().find(row=>row.id===b.dataset.tacticalPlayer);commitTacticalPosition(row.id,[Math.max(7,Math.min(93,row.x+delta[0])),Math.max(8,Math.min(92,row.y+delta[1]))]);};
}
const tacticalEditorHost=document.createElement('section');tacticalEditorHost.id='tactical-editor';$('match-popup-tactics').prepend(tacticalEditorHost);
